package com.mangashelf.mojian;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.provider.DocumentsContract;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class ReaderInstrumentation extends Instrumentation {
    final ArrayList<String> passed=new ArrayList<>();MainActivity activity;Bundle args;
    @Override public void onCreate(Bundle args){super.onCreate(args);this.args=args;start();}
    void check(boolean test,String message){if(!test)throw new AssertionError(message);}
    void ok(String name){passed.add(name);Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}
    void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
    void waitRender()throws Exception{long end=System.currentTimeMillis()+20000;while(System.currentTimeMillis()<end){waitForIdleSync();if(activity.loading!=null&&activity.loading.getVisibility()!=android.view.View.VISIBLE&&activity.pageView.bitmap!=null)return;Thread.sleep(50);}throw new AssertionError("PDF render timeout");}
    void waitImport()throws Exception{long end=System.currentTimeMillis()+30000;while(System.currentTimeMillis()<end){waitForIdleSync();if(!activity.busy)return;Thread.sleep(50);}throw new AssertionError("Import timeout");}
    void swipe()throws Exception{int[] xy=new int[2];ui(()->activity.pageView.getLocationOnScreen(xy));float y=xy[1]+activity.pageView.getHeight()*.5f,x=xy[0]+activity.pageView.getWidth()*.8f;long now=SystemClock.uptimeMillis();sendPointerSync(android.view.MotionEvent.obtain(now,now,0,x,y,0));for(int i=1;i<=8;i++){Thread.sleep(15);sendPointerSync(android.view.MotionEvent.obtain(now,SystemClock.uptimeMillis(),2,x-activity.pageView.getWidth()*.6f*i/8,y,0));}sendPointerSync(android.view.MotionEvent.obtain(now,SystemClock.uptimeMillis(),1,xy[0]+activity.pageView.getWidth()*.2f,y,0));Thread.sleep(200);}
    void screenshot(String name)throws Exception{if(activity!=null)ui(()->{if(activity.lastToast!=null)activity.lastToast.cancel();});waitForIdleSync();Thread.sleep(350);Bitmap bitmap=getUiAutomation().takeScreenshot();File out=new File(getTargetContext().getExternalFilesDir(null),name+".png");try(OutputStream stream=new FileOutputStream(out)){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}
    Uri uri(String id){return DocumentsContract.buildDocumentUriUsingTree(DocumentsContract.buildTreeDocumentUri("com.mangashelf.mojian.tests.documents",id),id);}
    @Override public void onStart(){Bundle result=new Bundle();try{
        if(args!=null&&"true".equals(args.getString("nativeSmoke"))){nativeSmoke();result.putString("stream","PASS native_system_picker_persistent_grant_restart_and_update\nPASS native_imported_pdf_reading\n");finish(Activity.RESULT_OK,result);return;}
        getUiAutomation().adoptShellPermissionIdentity("android.permission.MANAGE_DOCUMENTS");
        check(ChapterOrder.number("第十二话.pdf")==12,"Chinese chapter");check(ChapterOrder.number("chapter 2.5.pdf")==2.5,"Decimal chapter");check(ChapterOrder.number("【023】故事.pdf")==23,"Bracket chapter");check(ChapterOrder.number("第二百零三话.pdf")==203,"Hundreds");check(ChapterOrder.compare("第2话.pdf","第12话.pdf")<0,"Numeric sort");check(ChapterOrder.compare("番外1.pdf","第100话.pdf")>0,"Special last");check(ChapterOrder.start(3,5,true)==2&&ChapterOrder.start(4,5,true)==4,"Spread pairing");ok("chapter_order_and_pairing");
        Intent intent=new Intent(getTargetContext(),MainActivity.class);intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(MainActivity)startActivitySync(intent);waitForIdleSync();ui(()->activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));Thread.sleep(800);check(activity.library.books.isEmpty(),"Test must start with an empty application library");screenshot("home-empty");
        ui(()->activity.startImport(uri("A"),false));waitImport();check(activity.library.books.size()==1,"Imported book");final Library.Book book=activity.library.books.get(0);check(book.title.equals("森间来信"),"Folder name default");check(book.chapters.size()==4,"Recursive PDF count");check(book.chapters.get(0).name.equals("chapter 1"),"Chapter 1 first");check(book.chapters.get(1).name.equals("第2话"),"Chapter 2");check(book.chapters.get(2).name.equals("第十二话"),"Chapter 12");check(book.chapters.get(3).name.equals("番外"),"Special last");ok("saf_recursive_import_default_title_and_order");
        ui(()->{book.title="森间来信 · 我的收藏";activity.persist();activity.prefs.edit().putString("layout","dual").putBoolean("rtl",false).apply();activity.openReader(book,0,0);});waitRender();Bitmap bmp=activity.pageView.bitmap;int left=bmp.getPixel(5,bmp.getHeight()/2),right=bmp.getPixel(bmp.getWidth()-6,bmp.getHeight()/2);check(left!=right,"Two real distinct PDF pages");check(Color.alpha(bmp.getPixel(bmp.getWidth()/2,bmp.getHeight()/2))==0,"Transparent plain gutter");check(book.page==1,"Progress stores last visible page");screenshot("reader-dual");ok("real_pdf_dual_page_flat_gutter_and_progress");
        ui(()->activity.prefs.edit().putBoolean("rtl",true).apply());ui(()->activity.renderPage(0,false));waitRender();check(activity.pageView.bitmap.getPixel(5,bmp.getHeight()/2)==right,"RTL page order");ok("rtl_reverses_visual_order");
        ui(()->activity.step(1));waitRender();check(activity.page==2&&book.page==2,"Odd final page alone");check((float)activity.pageView.bitmap.getWidth()/activity.pageView.bitmap.getHeight()<.7f,"Odd page has no synthetic blank");ui(()->activity.step(1));waitRender();check(activity.chapterIndex==1&&activity.page==0,"Next chapter");ui(()->activity.step(-1));waitRender();check(activity.chapterIndex==0&&activity.page==2,"Previous chapter final spread");ok("odd_last_page_and_cross_chapter_navigation");
        ui(()->{activity.prefs.edit().putString("layout","single").putBoolean("rtl",false).putInt("effect",1).apply();activity.page=0;activity.renderPage(1,true);});waitRender();swipe();waitRender();check(activity.page==1&&book.page==1,"Touch swipe advances one page");ok("real_touch_swipe_turns_page");ui(()->activity.toggleTools());check(!activity.chrome,"Hide tools");ui(()->activity.toggleTools());check(activity.chrome,"Show tools");ui(()->activity.readerOptions());screenshot("reader-settings");getUiAutomation().performGlobalAction(1);waitForIdleSync();ui(()->activity.closeReader());ok("single_page_tools_and_settings");
        Library restored=new Library(getTargetContext());check(restored.books.get(0).title.equals("森间来信 · 我的收藏"),"Custom title persisted");check(restored.books.get(0).page==1,"Reading position persisted");ok("library_title_and_progress_persistence");
        getContext().getContentResolver().call(Uri.parse("content://com.mangashelf.mojian.tests.documents"),"append",null,null);
        ui(()->activity.startImport(uri("A"),false));waitImport();Library.Book current=activity.library.books.get(0);check(activity.library.books.size()==1&&current.chapters.size()==5,"Update deduplicates and adds chapter");check(current.title.equals("森间来信 · 我的收藏")&&current.page==1,"Update preserves metadata");check(current.chapters.get(2).name.equals("第3话"),"Updated chapter order");ok("rescan_updates_preserving_name_and_progress");
        getContext().getContentResolver().call(Uri.parse("content://com.mangashelf.mojian.tests.documents"),"break",null,null);Library.Progress progress=new Library.Progress(){public void update(String s){}public boolean cancelled(){return false;}};
        boolean failed=false;try{activity.library.importFolder(uri("A"),current,progress);}catch(IOException e){failed=true;}check(failed,"Corrupt PDF rejected");check(activity.library.file(current.chapters.get(2)).length()>100,"Old imported snapshot intact");check(new Library(getTargetContext()).books.get(0).chapters.size()==5,"Old index intact");check(Arrays.stream(activity.library.booksDir.listFiles()).noneMatch(f->f.getName().startsWith(".incoming-")),"No staging leftovers");ok("corrupt_update_rolls_back_and_cleans_staging");
        boolean cancelled=false;try{activity.library.importFolder(uri("B"),null,new Library.Progress(){boolean cancel=false;public void update(String s){cancel=true;}public boolean cancelled(){return cancel;}});}catch(InterruptedIOException e){cancelled=true;}check(cancelled&&activity.library.books.size()==1,"Cancel preserves library");check(Arrays.stream(activity.library.booksDir.listFiles()).noneMatch(f->f.getName().startsWith(".incoming-")),"Cancelled copy cleans staging");ok("cancel_during_copy_keeps_existing_books");
        ui(()->activity.startImport(uri("B"),false));waitImport();check(activity.library.books.size()==2,"Second book");screenshot("library");ui(()->activity.showBook(current));screenshot("book");ui(()->activity.showSettings());screenshot("preferences");ok("phone_library_details_and_preferences_ui");
        // Direct renderer also verifies the PDF remains readable after the source was corrupted.
        PdfEngine.Spread standalone=PdfEngine.render(activity.library.file(current.chapters.get(2)),0,true,false,1080,1600);check(standalone.total==2,"Managed PDF independent of original");standalone.bitmap.recycle();ok("managed_copy_reads_without_original");
        ui(()->{activity.prefs.edit().putString("layout","auto").apply();activity.openReader(current,0,1);});waitRender();check(!activity.dual(),"Portrait auto is single");screenshot("reader-portrait");ok("portrait_auto_single");
        ui(()->activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));Thread.sleep(800);waitRender();check(activity.dual(),"Landscape auto is dual");screenshot("reader-landscape");ui(()->activity.chooseLayout());screenshot("layout-choices");getUiAutomation().performGlobalAction(1);waitForIdleSync();ok("rotation_auto_dual_and_layout_choices");
        ui(()->activity.closeReader());getContext().getContentResolver().call(Uri.parse("content://com.mangashelf.mojian.tests.documents"),"addBook",null,null);ui(()->activity.startImport(uri("root"),true));waitImport();check(activity.library.books.size()==3,"Root adds third book and deduplicates old grants");check(activity.library.books.get(0).title.equals(current.title),"Root keeps custom title despite invalid source chapter");getUiAutomation().performGlobalAction(1);waitForIdleSync();ok("root_scan_deduplicates_across_tree_grants_and_handles_bad_books");
        ui(()->activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED));result.putString("stream","\n"+passed.size()+" checks passed\n"+String.join("\n",passed));result.putInt("passed",passed.size());finish(Activity.RESULT_OK,result);
    }catch(Throwable e){try{screenshot("failure");}catch(Exception ignored){}StringWriter sw=new StringWriter();e.printStackTrace(new PrintWriter(sw));result.putString("stream","FAILED after "+passed.size()+" checks\n"+sw);finish(Activity.RESULT_CANCELED,result);}}
    void nativeSmoke()throws Exception{
        activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
        Library.Book imported=null;for(Library.Book b:activity.library.books)if(b.title.startsWith("Mojian-Smoke-"))imported=b;check(imported!=null,"System picker import persisted across process restart");
        boolean grant=false;for(android.content.UriPermission p:getTargetContext().getContentResolver().getPersistedUriPermissions())if(p.isReadPermission()&&p.getUri().toString().contains("Mojian-Smoke-"))grant=true;check(grant,"Read permission is persisted by the real system picker");
        Library.Book before=imported;String oldPath=before.chapters.get(0).path;ui(()->activity.startImport(Uri.parse(before.source),false));waitImport();Library.Book after=activity.library.findSource(before.source);check(after!=null&&!after.chapters.get(0).path.equals(oldPath),"Normal app identity can re-read authorized source after restart");check(after.chapters.get(0).pages==1,"Real PDF counted");
        ui(()->{activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);activity.openReader(after,0,0);});Thread.sleep(700);waitRender();check(activity.pageView.bitmap!=null,"Native imported PDF renders");screenshot("native-pdf");ui(()->activity.closeReader());ui(()->activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED));
    }
}
